const binary = $input.item.binary || {};
const keys = Object.keys(binary);

// A founder's email may include a cover note, logo, or NDA alongside the
// actual deck. Pick the largest PDF attachment as the deck - real decks are
// almost always the biggest file by a wide margin.
const pdfCandidates = keys.filter((k) => {
  const b = binary[k] || {};
  const mt = (b.mimeType || '').toLowerCase();
  const ext = (b.fileExtension || '').toLowerCase();
  return mt.includes('pdf') || ext === 'pdf';
});

let chosen = null;
if (pdfCandidates.length > 0) {
  chosen = pdfCandidates.reduce((best, k) => {
    const size = (key) => Number((binary[key] && binary[key].bytes) || 0);
    return size(k) > size(best) ? k : best;
  }, pdfCandidates[0]);
}

// No PDF found (e.g. only a .pptx/.docx, or a link-only email that still had
// some other attachment) - deliberately point at a property that doesn't
// exist. Extract from File will then produce no usable text, and the
// Deck Text Extracted? gate downstream routes it to manual review instead
// of guessing which file to parse.
$input.item.json.deckAttachmentProperty = chosen || 'no_pdf_attachment_found';
$input.item.json.attachmentCount = keys.length;
$input.item.json.pdfAttachmentCount = pdfCandidates.length;

return $input.item;

